{
    "name": "app/doctrine-sqlite-no-interfaces-services-tests",
    "description": "Data access layer generated by DB2CRUD (Doctrine ORM 3)",
    "type": "project",
    "license": "proprietary",
    "require": {
        "php": ">=8.4",
        "ext-mbstring": "*",
        "ext-pdo_sqlite": "*",
        "doctrine/dbal": "^4.3",
        "doctrine/orm": "^3.5",
        "symfony/cache": "^7.3 || ^8.0"
    },
    "require-dev": {
        "phpunit/phpunit": "^12.4"
    },
    "autoload": {
        "psr-4": {
            "App\\": "src/"
        }
    },
    "autoload-dev": {
        "psr-4": {
            "Tests\\": "tests/"
        }
    },
    "scripts": {
        "test": "phpunit"
    },
    "config": {
        "sort-packages": true
    }
}

